CREATE TYPE "communication_audience" AS ENUM ('ALL','STAFF','FAMILIES','STUDENTS');
CREATE TYPE "homework_status" AS ENUM ('DRAFT','PUBLISHED');
CREATE TABLE "announcements" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"audience" "communication_audience" NOT NULL DEFAULT 'ALL',"published_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expires_at" TIMESTAMPTZ(3),"created_by_user_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "announcements_pkey" PRIMARY KEY("id"),CONSTRAINT "announcements_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "announcements_school_id_published_at_idx" ON "announcements"("school_id","published_at");
CREATE TABLE "school_events" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"location" TEXT,"audience" "communication_audience" NOT NULL DEFAULT 'ALL',"starts_at" TIMESTAMPTZ(3) NOT NULL,"ends_at" TIMESTAMPTZ(3) NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "school_events_pkey" PRIMARY KEY("id"),CONSTRAINT "school_events_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "school_events_dates_check" CHECK("ends_at">"starts_at"));
CREATE INDEX "school_events_school_id_starts_at_idx" ON "school_events"("school_id","starts_at");
CREATE TABLE "homework" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"academic_year_id" UUID NOT NULL,"class_id" UUID NOT NULL,"subject_id" UUID NOT NULL,"title" TEXT NOT NULL,"instructions" TEXT NOT NULL,"due_at" TIMESTAMPTZ(3) NOT NULL,"status" "homework_status" NOT NULL DEFAULT 'DRAFT',"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "homework_pkey" PRIMARY KEY("id"),CONSTRAINT "homework_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "homework_academic_year_id_fkey" FOREIGN KEY("academic_year_id") REFERENCES "academic_years"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "homework_class_id_fkey" FOREIGN KEY("class_id") REFERENCES "classes"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "homework_subject_id_fkey" FOREIGN KEY("subject_id") REFERENCES "subjects"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "homework_school_id_academic_year_id_due_at_idx" ON "homework"("school_id","academic_year_id","due_at");
CREATE TABLE "school_messages" ("id" UUID NOT NULL DEFAULT uuidv7(),"school_id" UUID NOT NULL,"sender_user_id" UUID NOT NULL,"recipient_user_id" UUID NOT NULL,"subject" TEXT NOT NULL,"body" TEXT NOT NULL,"sent_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"read_at" TIMESTAMPTZ(3),CONSTRAINT "school_messages_pkey" PRIMARY KEY("id"),CONSTRAINT "school_messages_school_id_fkey" FOREIGN KEY("school_id") REFERENCES "schools"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "school_messages_school_id_recipient_user_id_sent_at_idx" ON "school_messages"("school_id","recipient_user_id","sent_at");
CREATE INDEX "school_messages_school_id_sender_user_id_sent_at_idx" ON "school_messages"("school_id","sender_user_id","sent_at");
